INSERT INTO _patch VALUES
('p1','a1','{"title":"Revisão de cláusula compromissória","shortTitle":"Revisão de cláusula","duration":"30–60 min","summary":"Revisar a cláusula e apontar riscos de validade","demandBody":"Rebeca, chegou o contrato da Helvetia com a Nordeste. Antes de qualquer providência, revisa a cláusula compromissória: cabimento, instituição, sede, número de árbitros, idioma e se ela preenche os requisitos de validade. A Nordeste já ameaça dizer que é inválida. Me manda um parecer curto, de até duas páginas, com os riscos e a redação que você sugeriria."}'),
('p1','a2','{"title":"Redação de requerimento de arbitragem","shortTitle":"Requerimento de arbitragem"}'),
('p1','a3','{"title":"Indicação de árbitro","shortTitle":"Indicação de árbitro","summary":"Pesquisa de perfil e checagem de conflito de interesses"}'),
('p1','a4','{"title":"Pesquisa sobre jurisdição","shortTitle":"Pesquisa sobre jurisdição","duration":"1–2 h","summary":"Pesquisar doutrina e jurisprudência sobre a competência do tribunal arbitral","demandBody":"Rebeca, a Nordeste ajuizou ação no Judiciário dizendo que a cláusula é inválida e que o tribunal arbitral não tem jurisdição. Faz uma pesquisa sobre o tema: competência-competência (art. 8º, parágrafo único, da Lei de Arbitragem), cláusula patológica sem indicação precisa da instituição e como o STJ e o TJSP têm decidido. Me manda um memorando de até quatro páginas, com os precedentes citados corretamente e os que são contrários a nós."}'),
('p1','a5','{"title":"Desenvolvimento de written statement","shortTitle":"Written statement","duration":"1–2 h","summary":"Redigir a declaração escrita de testemunha","demandBody":"Rebeca, o tribunal fixou prazo para as declarações escritas de testemunhas. Vamos apresentar o written statement do gerente de qualidade da Helvetia sobre as entregas de 2025 e a ausência de qualquer recusa da Nordeste nos dez dias do contrato. Monta a declaração a partir das notas da entrevista e dos documentos: em primeira pessoa, em parágrafos numerados, só com fatos que ele presenciou e com a referência a cada documento. Até seis páginas."}'),
('p1','a6','{"title":"Análise de sentença arbitral","shortTitle":"Análise de sentença","duration":"1–2 h","summary":"Analisar a sentença e definir os próximos passos","demandBody":"Rebeca, saiu a sentença. Lê com atenção e me manda uma análise de até três páginas: se ela cumpre os requisitos do art. 26 da Lei de Arbitragem, se ficou algum pedido sem decisão, alguma contradição ou erro material, e se recomendamos pedido de esclarecimentos (art. 30, prazo de cinco dias) ou se há algum vício que justificaria ação anulatória. Indica os prazos contados da ciência."}'),
('p2','a1','{"title":"Aula 1 — Fase contratual","shortTitle":"Fase contratual","duration":"45–60 min","summary":"Meios alternativos de resolução de conflitos · Princípios e natureza da arbitragem · Validade de cláusulas compromissórias · Estratégia comercial aplicada à convenção de arbitragem"}'),
('p2','a2','{"title":"Aula 2 — Fase cautelar","shortTitle":"Fase cautelar","duration":"45–60 min","summary":"Ação do art. 7º da LArb · Tutela cautelar pré-arbitral · Árbitro de emergência · Produção antecipada de provas em arbitragem"}'),
('p2','a3','{"title":"Aula 3 — Fase de instauração","shortTitle":"Fase de instauração","duration":"45–60 min","summary":"Análise estratégica do pleito · Redação de requerimento de arbitragem · Seleção de árbitros · Esclarecimentos e impugnações"}'),
('p2','a4','{"title":"Aula 4 — Fase administrativa","shortTitle":"Fase administrativa","duration":"45–60 min","summary":"Termo de Arbitragem: parte processual · Termo de Arbitragem: parte material · Técnicas de organização do procedimento arbitral · Arbitragem expedita"}'),
('p2','a5','{"title":"Aula 5 — Fase instrutória","shortTitle":"Fase instrutória","duration":"45–60 min","summary":"Alegações iniciais e resposta com reconvenção · Construção da tese de pleitos complexos · Estratégias de convencimento do tribunal · Apoio técnico em arbitragens setoriais"}'),
('p2','a6','{"title":"Aula 6 — Provas","shortTitle":"Provas","duration":"45–60 min","summary":"Dinâmica probatória em sede de arbitragem · Pedido de produção de documentos · Perícia: quesitagem e definição de escopo · Perícia: contestação do laudo"}'),
('p2','a7','{"title":"Aula 7 — Audiências","shortTitle":"Audiências","duration":"45–60 min","summary":"Audiência de apresentação do caso · Audiência de instrução · Written statements · Interrogatório e contrainterrogatório de testemunhas"}'),
('p2','a8','{"title":"Aula 8 — Fase executória","shortTitle":"Fase executória","duration":"45–60 min","summary":"Elementos de uma sentença arbitral · Análise e pedido de esclarecimentos · Anulação e complementação da sentença · Homologação de sentença estrangeira"}');
