CREATE TEMP TABLE _patch(pid text, aid text, j jsonb) ON COMMIT DROP;
UPDATE public.learning_programs p SET content = jsonb_set(p.content,'{activities}',(SELECT jsonb_agg(a || COALESCE((SELECT j FROM _patch WHERE pid=p.id AND aid=a->>'id'),'{}'::jsonb) ORDER BY o) FROM jsonb_array_elements(p.content->'activities') WITH ORDINALITY t(a,o))), updated_at=now() WHERE p.id IN ('p1','p2');
UPDATE public.learning_programs SET content = content || '{"skills":["Cláusula compromissória","Requerimento de arbitragem","Indicação de árbitro","Jurisdição","Written statement","Sentença arbitral"],"learn":["Analisar a validade de uma cláusula compromissória e responder a quem a ataca","Redigir requerimento de arbitragem e written statement de testemunha","Indicar árbitros e conduzir a checagem de conflito de interesses","Pesquisar jurisdição e analisar a sentença arbitral para definir os próximos passos","Usar IA no limite do que o escritório aceita"]}'::jsonb WHERE id='p1';
UPDATE public.learning_programs SET content = content || '{"skills":["Fase contratual","Fase cautelar","Instauração","Termo de arbitragem","Instrução e provas","Audiências","Sentença e execução"],"learn":["O procedimento arbitral fase a fase, da fase contratual à executória","Cautelares, instauração, termo de arbitragem, instrução, provas e audiências","Como adaptar modelos às particularidades do caso"]}'::jsonb WHERE id='p2';